1	package agentusage
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"math"
7		"os"
8		"path/filepath"
9		"strings"
10		"testing"
11	)
12	
13	// crossCheckTolerance is the largest relative gap accepted between our totals
14	// and the reference tool's (acceptance criterion 5 of DEVDESK-40).
15	const crossCheckTolerance = 0.02
16	
17	const (
18		envReference = "DEVDESK_CCUSAGE_REF"
19		envProjects  = "DEVDESK_CLAUDE_PROJECTS"
20	)
21	
22	// refSession is one session of the reference file. Only Total is required;
23	// the other counters are compared when present.
24	type refSession struct {
25		ID         string `json:"id"`
26		Total      *int64 `json:"total"`
27		Input      *int64 `json:"input"`
28		Output     *int64 `json:"output"`
29		CacheRead  *int64 `json:"cacheRead"`
30		CacheWrite *int64 `json:"cacheWrite"`
31	}
32	
33	type refFile struct {
34		Sessions []refSession `json:"sessions"`
35	}
36	
37	// metricReport is one compared counter. It never carries content or a path.
38	type metricReport struct {
39		Name      string
40		Got, Want int64
41		Deviation float64
42		OK        bool
43	}
44	
45	// sessionReport is the outcome for one reference session.
46	type sessionReport struct {
47		ID      string
48		Missing bool   // no transcript found under the root
49		Err     string // locate or parse failure, without paths
50		Agents  int
51		Diag    Diagnostics
52		Metrics []metricReport
53	}
54	
55	// OK reports whether the session was found and every metric is in tolerance.
56	func (r sessionReport) OK() bool {
57		if r.Missing || r.Err != "" {
58			return false
59		}
60		for _, m := range r.Metrics {
61			if !m.OK {
62				return false
63			}
64		}
65		return len(r.Metrics) > 0
66	}
67	
68	// deviation is |got-want| / want; a zero reference only matches a zero count.
69	func deviation(got, want int64) float64 {
70		if want == 0 {
71			if got == 0 {
72				return 0
73			}
74			return 1
75		}
76		return math.Abs(float64(got-want)) / math.Abs(float64(want))
77	}
78	
79	func newMetric(name string, got int64, want *int64, tol float64) (metricReport, bool) {
80		if want == nil {
81			return metricReport{}, false
82		}
83		d := deviation(got, *want)
84		return metricReport{Name: name, Got: got, Want: *want, Deviation: d, OK: d < tol}, true
85	}
86	
87	// findTranscript looks for <root>/*/<id>.jsonl and returns its path.
88	func findTranscript(root, id string) (string, bool) {
89		if id == "" || id != filepath.Base(id) || strings.ContainsAny(id, `*?[\`) {
90			return "", false
91		}
92		dirs, err := os.ReadDir(root)
93		if err != nil {
94			return "", false
95		}
96		for _, d := range dirs {
97			if !d.IsDir() {
98				continue
99			}
100			p := filepath.Join(root, d.Name(), id+transcriptExt)
101			if fi, err := os.Lstat(p); err == nil && fi.Mode().IsRegular() {
102				return p, true
103			}
104		}
105		return "", false
106	}
107	
108	// compareToReference reads the reference file and compares every session it
109	// lists with what ParseSession computes from the transcripts under root. An
110	// unreadable or invalid reference is an error; a session problem is reported
111	// in its sessionReport.
112	func compareToReference(refPath, root string, tol float64) ([]sessionReport, error) {
113		raw, err := os.ReadFile(refPath)
114		if err != nil {
115			return nil, fmt.Errorf("reading reference file: %w", err)
116		}
117		var ref refFile
118		if err := json.Unmarshal(raw, &ref); err != nil {
119			return nil, fmt.Errorf("reference file is not valid JSON")
120		}
121		if len(ref.Sessions) == 0 {
122			return nil, fmt.Errorf("reference file lists no session")
123		}
124		reports := make([]sessionReport, 0, len(ref.Sessions))
125		for _, s := range ref.Sessions {
126			reports = append(reports, compareSession(s, root, tol))
127		}
128		return reports, nil
129	}
130	
131	func compareSession(s refSession, root string, tol float64) sessionReport {
132		rep := sessionReport{ID: s.ID}
133		if s.Total == nil {
134			rep.Err = "reference session has no total"
135			return rep
136		}
137		path, ok := findTranscript(root, s.ID)
138		if !ok {
139			rep.Missing = true
140			return rep
141		}
142		files, err := LocateSession(path)
143		if err != nil {
144			rep.Err = "locate failed"
145			return rep
146		}
147		u, err := ParseSession(files)
148		if err != nil {
149			rep.Err = "parse failed"
150			return rep
151		}
152		rep.Agents, rep.Diag = len(u.Agents), u.Diagnostics
153		tot := u.Total()
154		for _, c := range []struct {
155			name string
156			got  int64
157			want *int64
158		}{
159			{"total", tot.Total(), s.Total},
160			{"input", tot.Input, s.Input},
161			{"output", tot.Output, s.Output},
162			{"cacheRead", tot.CacheRead, s.CacheRead},
163			{"cacheWrite", tot.CacheWrite, s.CacheWrite},
164		} {
165			if m, ok := newMetric(c.name, c.got, c.want, tol); ok {
166				rep.Metrics = append(rep.Metrics, m)
167			}
168		}
169		return rep
170	}
171	
172	// diagCounters renders Diagnostics as counters only.
173	func diagCounters(d Diagnostics) string {
174		return fmt.Sprintf("unreadable=%d oversized=%d noUsage=%d noMsgID=%d crossFileDup=%d metaMissing=%d metaUnreadable=%d truncatedFiles=%d fileIssues=%d",
175			d.UnreadableLines, d.OversizedLines, d.NoUsage, d.NoMessageID, d.CrossFileDuplicates,
176			d.MetaMissing, d.MetaUnreadable, len(d.TruncatedFiles), len(d.Files))
177	}
178	
179	// TestSessionTotalsMatchCcusage is the real-data check of acceptance
180	// criterion 5. It needs a reference file kept outside the repository, so it
181	// is skipped unless DEVDESK_CCUSAGE_REF is set (CI never sets it).
182	func TestSessionTotalsMatchCcusage(t *testing.T) {
183		refPath := os.Getenv(envReference)
184		if refPath == "" {
185			t.Skipf("%s not set: no ccusage reference file, cross-check skipped", envReference)
186		}
187		root := os.Getenv(envProjects)
188		if root == "" {
189			var err error
190			if root, err = ProjectsRoot(); err != nil {
191				t.Fatalf("no transcripts root: %v", err)
192			}
193		}
194		reports, err := compareToReference(refPath, root, crossCheckTolerance)
195		if err != nil {
196			t.Fatal(err)
197		}
198		for _, r := range reports {
199			t.Logf("session %s: agents=%d diagnostics{%s}", r.ID, r.Agents, diagCounters(r.Diag))
200			for _, m := range r.Metrics {
201				t.Logf("  %-10s parsed=%d reference=%d deviation=%.4f%%", m.Name, m.Got, m.Want, m.Deviation*100)
202			}
203			switch {
204			case r.Missing:
205				t.Errorf("session %s: transcript not found under the projects root", r.ID)
206			case r.Err != "":
207				t.Errorf("session %s: %s", r.ID, r.Err)
208			case !r.OK():
209				t.Errorf("session %s: deviation at or above %.0f%%", r.ID, crossCheckTolerance*100)
210			}
211		}
212	}
213	
214	// TestCompareToReference covers the comparison and the reference parsing
215	// without any external data.
216	func TestCompareToReference(t *testing.T) {
217		const id = "11111111-2222-3333-4444-555555555555"
218		root := t.TempDir()
219		proj := filepath.Join(root, "-some-project")
220		if err := os.MkdirAll(proj, 0o700); err != nil {
221			t.Fatal(err)
222		}
223		line := `{"message":{"id":"m1","model":"x","stop_reason":"end_turn","usage":{"input_tokens":400,"output_tokens":300,"cache_read_input_tokens":200,"cache_creation_input_tokens":100}}}` + "\n"
224		if err := os.WriteFile(filepath.Join(proj, id+transcriptExt), []byte(line), 0o600); err != nil {
225			t.Fatal(err)
226		}
227	
228		tests := []struct {
229			name     string
230			ref      string
231			wantErr  bool
232			missing  bool
233			wantOK   bool
234			wantDevs map[string]float64 // approximate, in fraction
235		}{
236			{"zero gap", `{"sessions":[{"id":"` + id + `","total":1000}]}`, false, false, true, map[string]float64{"total": 0}},
237			{"1.9 percent", `{"sessions":[{"id":"` + id + `","total":981}]}`, false, false, true, map[string]float64{"total": 0.01937}},
238			{"2.1 percent", `{"sessions":[{"id":"` + id + `","total":979}]}`, false, false, false, map[string]float64{"total": 0.02145}},
239			{"optional fields match", `{"sessions":[{"id":"` + id + `","total":1000,"input":400,"output":300,"cacheRead":200,"cacheWrite":100}]}`, false, false, true, map[string]float64{"input": 0, "cacheWrite": 0}},
240			{"optional field off", `{"sessions":[{"id":"` + id + `","total":1000,"output":100}]}`, false, false, false, map[string]float64{"output": 2}},
241			{"missing session", `{"sessions":[{"id":"99999999-2222-3333-4444-555555555555","total":1000}]}`, false, true, false, nil},
242			{"path-like id is not found", `{"sessions":[{"id":"../` + id + `","total":1000}]}`, false, true, false, nil},
243			{"no total", `{"sessions":[{"id":"` + id + `"}]}`, false, false, false, nil},
244			{"invalid JSON", `{"sessions":[`, true, false, false, nil},
245			{"no sessions", `{"sessions":[]}`, true, false, false, nil},
246		}
247		for _, tt := range tests {
248			t.Run(tt.name, func(t *testing.T) {
249				refPath := filepath.Join(t.TempDir(), "ref.json")
250				if err := os.WriteFile(refPath, []byte(tt.ref), 0o600); err != nil {
251					t.Fatal(err)
252				}
253				reps, err := compareToReference(refPath, root, crossCheckTolerance)
254				if (err != nil) != tt.wantErr {
255					t.Fatalf("err = %v, wantErr %v", err, tt.wantErr)
256				}
257				if tt.wantErr {
258					return
259				}
260				if len(reps) != 1 {
261					t.Fatalf("got %d reports", len(reps))
262				}
263				r := reps[0]
264				if r.Missing != tt.missing {
265					t.Errorf("Missing = %v, want %v", r.Missing, tt.missing)
266				}
267				if r.OK() != tt.wantOK {
268					t.Errorf("OK = %v, want %v (%+v)", r.OK(), tt.wantOK, r)
269				}
270				for _, m := range r.Metrics {
271					if want, ok := tt.wantDevs[m.Name]; ok && math.Abs(m.Deviation-want) > 1e-4 {
272						t.Errorf("%s deviation = %.5f, want %.5f", m.Name, m.Deviation, want)
273					}
274				}
275			})
276		}
277	
278		if _, err := compareToReference(filepath.Join(t.TempDir(), "absent.json"), root, crossCheckTolerance); err == nil {
279			t.Error("absent reference file: want an error")
280		}
281	}
