214	// TestCompareToReference covers the comparison and the reference parsing
215	// without any external data.
216	func TestCompareToReference(t *testing.T) {
217		const id = "11111111-2222-3333-4444-555555555555"
218		root := t.TempDir()
219		proj := filepath.Join(root, "-some-project")
220		if err := os.MkdirAll(proj, 0o700); err != nil {
