228		tests := []struct {
229			name     string
230			ref      string
231			wantErr  bool
232			missing  bool
233			wantOK   bool
234			wantDevs map[string]float64 // approximate, in fraction
235		}{
236			{"zero gap", `{"sessions":[{"id":"` + id + `","total":1000}]}`, false, false, true, map[string]float64{"total": 0}},
237			{"1.9 percent", `{"sessions":[{"id":"` + id + `","total":981}]}`, false, false, true, map[string]float64{"total": 0.01937}},
238			{"2.1 percent", `{"sessions":[{"id":"` + id + `","total":979}]}`, false, false, false, map[string]float64{"total": 0.02145}},
239			{"optional fields match", `{"sessions":[{"id":"` + id + `","total":1000,"input":400,"output":300,"cacheRead":200,"cacheWrite":100}]}`, false, false, true, map[string]float64{"input": 0, "cacheWrite": 0}},
240			{"optional field off", `{"sessions":[{"id":"` + id + `","total":1000,"output":100}]}`, false, false, false, map[string]float64{"output": 2}},
241			{"missing session", `{"sessions":[{"id":"99999999-2222-3333-4444-555555555555","total":1000}]}`, false, true, false, nil},
242			{"path-like id is not found", `{"sessions":[{"id":"../` + id + `","total":1000}]}`, false, true, false, nil},
243			{"no total", `{"sessions":[{"id":"` + id + `"}]}`, false, false, false, nil},
244			{"invalid JSON", `{"sessions":[`, true, false, false, nil},
245			{"no sessions", `{"sessions":[]}`, true, false, false, nil},
246		}
247		for _, tt := range tests {
248			t.Run(tt.name, func(t *testing.T) {
249				refPath := filepath.Join(t.TempDir(), "ref.json")
250				if err := os.WriteFile(refPath, []byte(tt.ref), 0o600); err != nil {
